// ia-ml pide: telegram | telegram-foto | push. La respuesta lleva { ok, ... } para que ia-ml decida si reintenta.
const crypto = require('crypto');
const { headers, body: b } = $input.first().json;
if (!$env.N8N_CLAVE || headers['x-clave-comedor'] !== $env.N8N_CLAVE) return [{ json: { ok: false, description: 'Clave incorrecta' } }];

const http = this.helpers.httpRequest;
const telegram = (metodo) => `https://api.telegram.org/bot${$env.TELEGRAM_BOT_TOKEN}/${metodo}`;

if (b.canal === 'telegram') {
  const r = await http({ method: 'POST', url: telegram(b.metodo), body: b.datos, json: true, ignoreHttpStatusErrors: true });
  return [{ json: r }];
}

if (b.canal === 'telegram-foto') {
  const limite = 'comedor' + Date.now();
  const campo = (n, v) => `--${limite}\r\nContent-Disposition: form-data; name="${n}"\r\n\r\n${v}\r\n`;
  const cuerpo = Buffer.concat([
    Buffer.from(campo('chat_id', b.chat_id) + campo('caption', b.caption || '') +
      `--${limite}\r\nContent-Disposition: form-data; name="photo"; filename="qr.png"\r\nContent-Type: image/png\r\n\r\n`),
    Buffer.from(b.png, 'base64'),
    Buffer.from(`\r\n--${limite}--\r\n`),
  ]);
  const r = await http({ method: 'POST', url: telegram('sendPhoto'), body: cuerpo,
    headers: { 'content-type': `multipart/form-data; boundary=${limite}` }, json: true, ignoreHttpStatusErrors: true });
  return [{ json: typeof r === 'string' ? JSON.parse(r) : r }];
}

if (b.canal === 'push') {
  if (!$env.FIREBASE_CREDENCIALES) return [{ json: { ok: false, description: 'Falta FIREBASE_CREDENCIALES en n8n' } }];
  const cred = JSON.parse($env.FIREBASE_CREDENCIALES);
  const memoria = $getWorkflowStaticData('global');
  if (!memoria.fcmToken || Date.now() > memoria.fcmVence) {
    const ahora = Math.floor(Date.now() / 1000);
    const b64 = (o) => Buffer.from(JSON.stringify(o)).toString('base64url');
    const sinFirma = b64({ alg: 'RS256', typ: 'JWT' }) + '.' + b64({
      iss: cred.client_email, scope: 'https://www.googleapis.com/auth/firebase.messaging',
      aud: 'https://oauth2.googleapis.com/token', iat: ahora, exp: ahora + 3600 });
    const firma = crypto.createSign('RSA-SHA256').update(sinFirma).sign(cred.private_key, 'base64url');
    const t = await http({ method: 'POST', url: 'https://oauth2.googleapis.com/token', json: true,
      headers: { 'content-type': 'application/x-www-form-urlencoded' },
      body: `grant_type=${encodeURIComponent('urn:ietf:params:oauth:grant-type:jwt-bearer')}&assertion=${sinFirma}.${firma}` });
    memoria.fcmToken = t.access_token;
    memoria.fcmVence = Date.now() + 50 * 60 * 1000;
  }
  const r = await http({ method: 'POST', url: `https://fcm.googleapis.com/v1/projects/${cred.project_id}/messages:send`,
    headers: { Authorization: `Bearer ${memoria.fcmToken}` }, json: true, returnFullResponse: true, ignoreHttpStatusErrors: true,
    body: { message: { token: b.token, notification: { title: b.titulo, body: b.cuerpo }, data: b.datos || {},
      android: { priority: 'HIGH', ttl: b.vigencia, collapse_key: (b.datos || {}).tipo || 'aviso', notification: { channel_id: b.canalAndroid } } } } });
  if (r.statusCode === 200) return [{ json: { ok: true } }];
  if (r.statusCode === 401) delete memoria.fcmToken;
  const texto = JSON.stringify(r.body);
  const tokenInvalido = [404, 410].includes(r.statusCode) || texto.includes('UNREGISTERED') || texto.includes('INVALID_ARGUMENT');
  return [{ json: { ok: false, tokenInvalido, description: `FCM ${r.statusCode}: ${texto.slice(0, 160)}` } }];
}

return [{ json: { ok: false, description: `Canal desconocido: ${b.canal}` } }];
